import json,html
from pathlib import Path
R=Path(__file__).parent; legacy=json.loads((R/'results.json').read_text()); data=json.loads((R/'bank-results.json').read_text()); S=data['summary']
content=json.loads((R/'workshop-content.json').read_text())
slides=[(x['title'],x['subtitle'],x['bullets'],x['notes']) for x in content]
(R/'slides.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2))
css='''*{box-sizing:border-box}body{margin:0;background:#101728;color:#f0f4ff;font:20px system-ui}main{max-width:1200px;margin:auto;padding:36px}h1{font-size:48px;line-height:1.12;margin:10px 0 18px}h2{color:#75dfc8;font-size:25px}li{margin:18px 0;line-height:1.4}.slide{display:none;min-height:72vh}.slide.on{display:block}button,select{background:#23334d;color:white;border:1px solid #7587a4;padding:12px;border-radius:8px;font:inherit;margin:5px;cursor:pointer}button:hover{background:#345078}nav{display:flex;align-items:center;gap:12px;flex-wrap:wrap}small,.muted{color:#a9bbd6}details{margin:20px 0;font-size:16px}.speaker-notes{white-space:pre-line;line-height:1.65}.example{background:#18243b;border-left:4px solid #75dfc8;padding:16px;line-height:1.4}.flow{color:#75dfc8;padding:10px;font-size:24px}pre{white-space:pre-wrap;font:15px ui-monospace;background:#18243b;padding:15px;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:18px}td,th{text-align:left;border-bottom:1px solid #354561;padding:10px}svg{width:100%;max-height:230px}a{color:#75dfc8}@media print{body{background:white;color:black}.slide{display:block!important;min-height:0;break-after:page}nav,.demo,details{display:none}main{padding:0}h1{font-size:32px}li{font-size:20px}small{color:#444}}'''
graph='''<svg viewBox="0 0 1000 160" role="img" aria-label="svc-0 depends_on db-0 owned_by team-0"><defs><marker id="a" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#75dfc8"/></marker></defs><g fill="#23334d" stroke="#75dfc8"><rect x="20" y="60" width="170" height="70" rx="12"/><rect x="400" y="60" width="170" height="70" rx="12"/><rect x="790" y="60" width="170" height="70" rx="12"/><path d="M190 95H390 M570 95H780" marker-end="url(#a)"/></g><g fill="white" font-size="24" text-anchor="middle"><text x="105" y="104">svc-0</text><text x="485" y="104">db-0</text><text x="875" y="104">team-0</text><text x="285" y="60">závisí na</text><text x="675" y="60">vlastní ji</text></g></svg>'''
def demo():return '''<div class="demo"><p>Ukázka vybírá uložené výsledky skutečného měření. Zvolte otázku a metodu, pak klikněte na odhalení. Nejde o živou odpověď LLM.</p><label>Otázka <select id="q"><option value="q-inc-0">A: podobný incident</option><option value="q-path-0">B: závislost a eskalace</option><option value="q-now-0">C: aktuální vlastník</option></select></label><label>Metoda <select id="m"><option>vector</option><option>graph</option><option>hybrid</option><option>full</option></select></label><button onclick="show()">Odhalit důkazy</button><pre id="out" aria-live="polite">Nejdřív tipněte výsledek. Gold znamená správné důkazy; ANO = našly se všechny.</pre></div>'''
parts=[]
for i,(title,sub,bullets,note) in enumerate(slides):
 extra=(R/'bank-visual-fragment.html').read_text() if i==4 else '<p><a href="bank-visual.html" target="_blank">Otevřít interaktivní bankovní příklady ↗</a></p><img src="bank-feature-evidence.png" alt="Dopady změny maržové funkce: skóre, report a dashboard" style="width:100%">' if i==5 else ''
 if i==1:
  extra='<p class="flow">Uložené zdroje → vyhledání → vybrané důkazy → model</p>'
 if i==9:
  extra='<img src="bank-health-evidence.png" alt="Aktuální verze v2 a tři komponenty mechanismu skóre" style="width:100%"><p><a href="bank-guide.md">Vstupy, formule a zdrojové soubory</a></p>'
 if i==8:
  extra='<p><a href="tools-comparison.html" target="_blank">Interaktivně porovnat dvojici nástrojů ↗</a> · <a href="tools-comparison.md">Podrobnosti a primární zdroje</a></p>'
 if i==7:
  extra='<table><tr><th>Metoda</th><th>Úplnost</th><th>Recall</th><th>Precision</th><th>ms*</th></tr>'+''.join(f"<tr><td>{x['method']}</td><td>{x['complete']}/3</td><td>{x['recall']:.2f}</td><td>{x['precision']:.2f}</td><td>{x['median_ms']:.6f}</td></tr>" for x in S)+'</table><small>* Medián mediánů na dotaz; in-process, bez plánování.</small>'
 visible='' if i in [4,5,9] else '<ul>'+''.join(f'<li>{html.escape(b)}</li>' for b in bullets)+'</ul><p class="example">'+html.escape(content[i]['example'])+'</p>'
 parts.append(f'<section class="slide {"on" if i==0 else ""}"><small>LLM MEMORY LAB • {i+1:02}/12</small><h1>{html.escape(title)}</h1><h2>{html.escape(sub)}</h2>'+visible+extra+f'<details><summary>Poznámky moderátora: text k přednesu a postup</summary><div class="speaker-notes">{html.escape(note)}</div></details></section>')
js='''let n=0;const slides=[...document.querySelectorAll('.slide')];function move(d){n=Math.max(0,Math.min(slides.length-1,n+d));slides.forEach((s,i)=>s.classList.toggle('on',i===n));document.getElementById('page').textContent=(n+1)+' / '+slides.length;}document.addEventListener('keydown',e=>{if(['SELECT','BUTTON'].includes(e.target.tagName))return;if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1);});function show(){const row=DATA.rows.find(r=>r.query===document.getElementById('q').value&&r.method===document.getElementById('m').value);const docs=row.retrieved.map(id=>DATA.documents.find(d=>d.id===id));document.getElementById('out').textContent='Gold (potřebné důkazy): '+row.gold.join(', ')+'\\nVráceno: '+row.retrieved.join(', ')+'\\nÚplné důkazy: '+(row.complete?'ANO':'NE')+' | Recall: '+row.recall+' | Kontext: '+row.context_bytes+' B\\n\\n'+docs.map(d=>d.id+': '+d.text).join('\\n\\n');}'''
(R/'presentation.html').write_text('<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paměť LLM agenta · workshop</title><style>'+css+'</style><main>'+''.join(parts)+'<nav><button onclick="move(-1)">← Zpět</button><span id="page">1 / 12</span><button onclick="move(1)">Dále →</button><button onclick="document.documentElement.requestFullscreen()">Celá obrazovka</button><button onclick="window.print()">PDF / tisk</button></nav></main><script>const DATA='+json.dumps(data)+';'+js+'</script></html>')
# standalone demo uses only the independent show function
(R/'demo.html').write_text('<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Retrieval: důkazy</title><style>'+css+'</style><main><h1>Kam zmizela druhá hrana?</h1>'+graph+demo()+'<p><a href="presentation.html">Prezentace</a> · <a href="results.json">Naměřená data</a></p></main><script>const DATA='+json.dumps(legacy)+';function show()'+js.split('function show()')[1]+'</script></html>')
notes=(R/'presenter-intro.md').read_text()+'\n\n'.join(f'## Slide {i+1}: {x[0]}\n\n{x[3]}' for i,x in enumerate(slides))+'\n\n'+(R/'presenter-faq.md').read_text()
(R/'facilitator.md').write_text(notes)
